function overviewPage(){
  const tx=state.transactions.slice().sort((a,b)=>dt(b.date)-dt(a.date));
  const os=state.orders.slice().sort((a,b)=>dt(b.date)-dt(a.date));
  const income=tx.filter(x=>x.type==='income').reduce((s,x)=>s+x.amount,0), expense=tx.filter(x=>x.type==='expense').reduce((s,x)=>s+x.amount,0), net=income-expense;
  const revenue=os.reduce((s,x)=>s+(+x.sell||0),0), profit=os.reduce((s,x)=>s+(+x.sell||0)-(+x.cost||0),0), debt=os.reduce((s,x)=>s+Math.max(0,(+x.sell||0)-(x.customerPaid??x.paid??x.customerDeposit??0)),0);
  const total=income+expense||1, ip=Math.round(income/total*100), ep=Math.round(expense/total*100);
  const recent=tx.slice(0,5).map(x=>'<div class="overview-row"><div class="overview-row-icon '+(x.type==='income'?'income':'')+'">'+(x.type==='income'?'↓':'↑')+'</div><div class="overview-row-main"><strong>'+esc(x.category)+'</strong><small>'+esc(x.note||'Không có ghi chú')+' · '+dtf(x.date)+'</small></div><b class="'+(x.type==='income'?'income':'red')+'">'+(x.type==='income'?'+':'-')+' '+fmt(x.amount)+'</b></div>').join('')||'<div class="empty">Chưa có hoạt động nào.</div>';
  return '<div class="overview-page"><div class="overview-hero"><div><span class="dashboard-kicker">TRUNG TÂM ĐIỀU HÀNH</span><h1>Xin chào, '+esc(state.profile.name||'bạn')+' <span>👋</span></h1><p>Bức tranh tổng thể về tài chính cá nhân và hoạt động kinh doanh của bạn.</p></div><div class="overview-hero-meta"><span class="pulse-dot"></span><span>Đồng bộ realtime</span><small>Cập nhật vừa xong</small></div></div><div class="overview-toolbar"><div><strong>Tổng quan tài chính</strong><span> Tất cả dữ liệu đang được tổng hợp</span></div><button class="btn btn-primary" id="overview-add">＋ Thêm giao dịch</button></div><div class="overview-kpis"><div class="overview-kpi kpi-main"><span>Số dư cá nhân</span><strong>'+fmt(net)+'</strong><small>'+(net>=0?'Tình hình đang tích cực':'Cần kiểm soát chi tiêu')+'</small><i>↗</i></div><div class="overview-kpi"><span>Thu nhập</span><strong class="income">'+fmt(income)+'</strong><small>'+ip+'% tổng dòng tiền</small><div class="kpi-bar"><b style="width:'+ip+'%"></b></div></div><div class="overview-kpi"><span>Chi tiêu</span><strong class="red">'+fmt(expense)+'</strong><small>'+ep+'% tổng dòng tiền</small><div class="kpi-bar expense-bar"><b style="width:'+ep+'%"></b></div></div><div class="overview-kpi"><span>Lợi nhuận kinh doanh</span><strong class="purple-value">'+fmt(profit)+'</strong><small>'+os.length+' đơn hàng</small></div></div><div class="overview-columns"><section class="card overview-card"><div class="card-head"><div><h3>Hoạt động gần đây</h3><span class="muted">Các giao dịch mới nhất</span></div><button class="overview-link" data-view="personal">Xem sổ giao dịch →</button></div><div class="overview-list">'+recent+'</div></section><section class="card overview-card"><div class="card-head"><div><h3>Kinh doanh tổng hợp</h3><span class="muted">Đơn hàng và công nợ</span></div><button class="overview-link" data-view="business">Mở kinh doanh →</button></div><div class="business-overview-total"><span>Doanh thu</span><strong>'+fmt(revenue)+'</strong></div><div class="mini-stat-list"><div><span>Lợi nhuận</span><b class="income">'+fmt(profit)+'</b></div><div><span>Công nợ phải thu</span><b class="amber">'+fmt(debt)+'</b></div><div><span>Số đơn hàng</span><b>'+os.length+'</b></div></div></section></div><div class="overview-bottom"><div class="overview-tip"><span class="tip-icon">✦</span><div><strong>Gợi ý tài chính</strong><p>'+(expense>income?'Chi tiêu đang cao hơn thu nhập. Hãy xem lại các khoản chi gần đây.':'Bạn đang duy trì dòng tiền cân đối. Tiếp tục theo dõi đều đặn.')+'</p></div></div><div class="overview-quick"><button data-view="notes"><span>✦</span>Ghi chú</button><button data-view="history"><span>◷</span>Lịch sử</button><button id="overview-profile"><span>⚙</span>Hồ sơ</button></div></div></div>';
}
