  layout=function(){layoutV11();installOverviewNavigation();if(view==='overview'){const c=document.querySelector('.content');if(c){c.innerHTML=overviewPage()+'<div class="footer-credit">Hệ thống được phát triển bởi Nguyễn Linh</div>'}const title=document.querySelector('.top-title');if(title) title.textContent='Tổng quan';installOverviewNavigation()}};
