const layoutLatest=layout;
layout=function(){layoutLatest();if(view==='business'){const grid=document.querySelector('.business-grid');if(grid&&!grid.querySelector('.delivery-due-card')){const n=deliveryDueOrders().length;grid.insertAdjacentHTML('beforeend',`<div class="card stat-card delivery-due-card" role="button" tabindex="0"><div class="stat-top">Đơn hàng đến hạn giao</div><h2 class="amber">${n}</h2><small>Trong 3 ngày gần nhất · Xem chi tiết</small></div>`);grid.querySelector('.delivery-due-card').onclick=deliveryDueModal}document.querySelectorAll('.business-grid .stat-card').forEach(c=>{const h=c.querySelector('.stat-top')?.textContent||'';if(h.includes('Công nợ phải thu')){c.classList.add('debt-clickable');c.onclick=()=>debtDetailModal('receivable')}if(h.includes('Công nợ phải trả')){c.classList.add('debt-clickable');c.onclick=()=>debtDetailModal('payable')}});document.querySelectorAll('.history-order').forEach(b=>b.onclick=()=>orderHistoryModal(b.dataset.id));document.querySelectorAll('.update-order').forEach(b=>b.onclick=()=>openModal('payment',state.orders.find(x=>x.id===b.dataset.id)))}};


// Sửa cuối luồng thanh toán: luôn render lại sau khi paymentHistory đã ghi.
const orderHistoryDetail=function(id){
  const o=state.orders.find(x=>x.id===id); if(!o)return;
  const panel=(party,label)=>{
    const rows=partyHistory(o,party),total=party==='customer'?+o.sell||0:+o.cost||0; let paid=0;
    const body=rows.length?rows.map(x=>{paid+=+x.amount||0;const remaining=Math.max(0,total-paid),status=paid<=0?'Chưa thanh toán':remaining?'Chưa đủ · còn '+fmt(remaining):'Đã thanh toán đủ';return '<div class="history-row"><div class="history-icon '+(party==='customer'?'income':'deleted')+'">'+(x.kind==='deposit'?'◈':'✓')+'</div><div class="history-main"><strong>'+(x.kind==='deposit'?'Đặt cọc':'Thanh toán thêm')+' · '+fmt(x.amount)+'</strong><div>'+dtf(x.date)+'</div><small class="history-status '+(remaining?'pending':'complete')+'">'+status+'</small></div></div>'}).join(''):'<div class="empty">Chưa có cập nhật.</div>';
    const status=paymentStatus(o,party); return '<section class="payment-history-panel"><div class="payment-history-title"><h3>'+label+'</h3><span class="badge '+(status.remaining?'badge-debt':'badge-paid')+'">'+status.label+'</span></div><div class="payment-history-summary">Đã thanh toán <b>'+fmt(status.paid)+'</b> · Còn lại <b class="'+(status.remaining?'red':'income')+'">'+fmt(status.remaining)+'</b></div>'+body+'</section>';
  };
  document.body.insertAdjacentHTML('beforeend','<div class="modal-back order-history-back"><div class="modal order-history-modal"><div class="modal-head"><div><h2>Lịch sử thanh toán</h2><span class="muted">'+esc(o.customer)+'</span></div><button class="close-history">×</button></div><div class="payment-history-grid">'+panel('customer','Khách hàng')+panel('supplier','Nhà cung cấp')+'</div><div class="form-actions"><button type="button" class="btn btn-primary close-history">Đóng</button></div></div></div>');
  document.querySelectorAll('.close-history').forEach(x=>x.onclick=()=>document.querySelector('.order-history-back')?.remove());
};
orderHistoryModal=orderHistoryDetail;
saveForm=function(e){
  if(e.currentTarget.id==='payment-form'){
    e.preventDefault();const f=new FormData(e.currentTarget),o=state.orders.find(x=>x.id===e.currentTarget.dataset.id);if(!o)return;
    const customerAdd=parseMoney(f.get('customerPay')),supplierAdd=parseMoney(f.get('supplierPay')),stamp=nowLocal();o.paymentHistory=o.paymentHistory||[];
    const customerBefore=Math.max(+o.customerPaid||+o.paid||0,+o.customerDeposit||0),supplierBefore=Math.max(+o.supplierPaid||0,+o.supplierDeposit||0);
    const customerNext=Math.min(+o.sell||0,customerBefore+customerAdd),supplierNext=Math.min(+o.cost||0,supplierBefore+supplierAdd);
    if(customerAdd){const amount=Math.min(customerAdd,Math.max(0,(+o.sell||0)-customerBefore));o.customerPaid=customerNext;o.customerLastPaymentAt=stamp;o.paymentHistory.push({party:'customer',kind:'payment',amount,date:stamp});state.businessBalance+=amount;state.balanceMoves.unshift({id:`m-${Date.now()}`,date:stamp,amount,note:`Khách ${o.customer} thanh toán`});}
    if(supplierAdd){const amount=Math.min(supplierAdd,Math.max(0,(+o.cost||0)-supplierBefore));o.supplierPaid=supplierNext;o.supplierLastPaymentAt=stamp;o.paymentHistory.push({party:'supplier',kind:'payment',amount,date:stamp});state.businessBalance-=amount;state.balanceMoves.unshift({id:`m-${Date.now()}-s`,date:stamp,amount:-amount,note:`Thanh toán nhà cung cấp cho ${o.customer}`});}
    save();document.querySelector('.modal-back')?.remove();layout();toast('Đã cập nhật thanh toán, công nợ và lịch sử');return;
  }
  saveFormV4(e);
};

/* Business workflow consolidation: order profit, full-payment shortcuts and delivery state. */
const businessOrdersRenderer=businessOrdersMarkup;
businessOrdersMarkup=function(items,compact=false){
  const active=(items||[]).filter(x=>!x.delivered);
  return businessOrdersRenderer(active,compact).replace(/<button class="icon-btn delete-order"/g,'<button class="icon-btn mark-delivered" data-delivery-action="mark"').replace(/>🗑 Xoá<\/button>/g,'>✓ Đã giao<\/button>');
};

const openModalBusinessFinal=openModal;
openModal=function(type,item={}){
  openModalBusinessFinal(type,item);
  if(type!=='order')return;
  const form=document.querySelector('#modal-form'), preview=form?.querySelector('.order-preview');
  if(!form||!preview||form.querySelector('.full-payment-options'))return;
  preview.insertAdjacentHTML('beforebegin',`<div class="field full full-payment-options"><label class="check-option"><input type="checkbox" name="customerPaidFull" ${item.id&&Math.max(item.customerPaid||item.paid||0,item.customerDeposit||0)>=item.sell?'checked':''}><span>Khách đã thanh toán đủ</span></label><label class="check-option"><input type="checkbox" name="supplierPaidFull" ${item.id&&(item.supplierPaid||item.supplierDeposit||0)>=item.cost?'checked':''}><span>Đã thanh toán đủ cho nhà cung cấp</span></label></div>`);
};

const saveFormBusinessFinal=saveForm;
saveForm=function(e){
  const form=e.currentTarget;
  if(form.dataset.type!=='order'){saveFormBusinessFinal(e);return;}
  const id=form.dataset.id, existing=id?state.orders.find(x=>x.id===id):null;
  const beforeCustomer=existing?Math.max(+existing.customerPaid||+existing.paid||0,+existing.customerDeposit||0):parseMoney(form.elements.customerDeposit?.value);
  const beforeSupplier=existing?Math.max(+existing.supplierPaid||0,+existing.supplierDeposit||0):parseMoney(form.elements.supplierDeposit?.value);
  const customerFull=form.elements.customerPaidFull?.checked===true, supplierFull=form.elements.supplierPaidFull?.checked===true;
  saveFormBusinessFinal(e);
  const order=id?state.orders.find(x=>x.id===id):state.orders[0];
  if(!order)return;
  order.paymentHistory=order.paymentHistory||[];
  const stamp=nowLocal(), customerTarget=customerFull?+order.sell||0:Math.max(+order.customerPaid||0,+order.customerDeposit||0), supplierTarget=supplierFull?+order.cost||0:Math.max(+order.supplierPaid||0,+order.supplierDeposit||0);
  const customerDelta=Math.max(0,customerTarget-beforeCustomer), supplierDelta=Math.max(0,supplierTarget-beforeSupplier);
  if(customerDelta){order.customerPaid=customerTarget;order.customerLastPaymentAt=stamp;order.paymentHistory.push({party:'customer',kind:'payment',amount:customerDelta,date:stamp});state.businessBalance+=customerDelta;state.balanceMoves.unshift({id:`order-customer-${Date.now()}`,date:stamp,amount:customerDelta,note:`Khách ${order.customer} thanh toán`});}
  if(supplierDelta){order.supplierPaid=supplierTarget;order.supplierLastPaymentAt=stamp;order.paymentHistory.push({party:'supplier',kind:'payment',amount:supplierDelta,date:stamp});state.businessBalance-=supplierDelta;state.balanceMoves.unshift({id:`order-supplier-${Date.now()}`,date:stamp,amount:-supplierDelta,note:`Thanh toán nhà cung cấp cho ${order.customer}`});}
  if(!existing){const profit=(+order.sell||0)-(+order.cost||0);if(profit){state.businessBalance+=profit;state.balanceMoves.unshift({id:`order-profit-${Date.now()}`,date:stamp,amount:profit,note:`Lợi nhuận đơn hàng ${order.customer}`});}}
  save();layout();toast('Đã lưu đơn hàng và cập nhật số dư');
};

function deliveredOrdersMarkup(){
  const delivered=state.orders.filter(x=>x.delivered).sort((a,b)=>dt(b.deliveredAt||b.date)-dt(a.deliveredAt||a.date));
  if(!delivered.length)return '<div class="empty">Chưa có đơn hàng đã giao.</div>';
  return delivered.slice(0,30).map(x=>`<div class="delivered-order-row"><div><strong>${esc(x.customer)}</strong><small>Giao lúc ${dtf(x.deliveredAt||x.date)}</small></div><span class="badge badge-paid">Đã giao</span><b>${fmt(x.sell)}</b></div>`).join('');
}
function installDeliveryWorkflow(){
  if(view!=='business')return;
  const grid=document.querySelector('.business-grid');
  if(grid&&!grid.querySelector('.delivered-count-card')){const card=document.createElement('div');card.className='card stat-card delivered-count-card';card.innerHTML=`<div class="stat-top">Đơn hàng đã giao</div><h2>${state.orders.filter(x=>x.delivered).length}</h2><small>Đã hoàn tất giao hàng</small>`;grid.appendChild(card)}
  const table=document.querySelector('.table-card');
  if(table&&!document.querySelector('.delivered-orders-panel'))table.insertAdjacentHTML('afterend',`<div class="card table-card delivered-orders-panel"><div class="card-head"><h3>Đơn hàng đã giao</h3><span class="muted">${state.orders.filter(x=>x.delivered).length} đơn</span></div>${deliveredOrdersMarkup()}</div>`);
  document.querySelectorAll('.mark-delivered').forEach(button=>button.onclick=()=>{const order=state.orders.find(x=>x.id===button.dataset.id);if(!order)return;order.delivered=true;order.deliveredAt=nowLocal();state.history.unshift({action:'Cập nhật',type:'order',label:`${order.customer} · Đã giao hàng`,date:order.deliveredAt});save();layout();toast('Đã chuyển đơn hàng sang Đơn hàng đã giao')});
}
const layoutBusinessWorkflow=layout;
layout=function(){layoutBusinessWorkflow();installDeliveryWorkflow();};

// Reliable cross-device sync: serialize writes and pull immediately when the tab is active again.
saveCloud=async function(data){
  if(!cloudUser||!supabase)return;
  const snapshot=JSON.parse(JSON.stringify(data)),updatedAt=new Date().toISOString();
  cloudWriteChain=cloudWriteChain.then(async()=>{
    const {error}=await supabase.from('app_states').upsert({user_id:cloudUser.id,data:snapshot,updated_at:updatedAt});
    if(error)toast('Không thể đồng bộ: '+error.message);else {cloudLastUpdated=updatedAt;cloudChannel?.send({type:'broadcast',event:'state_updated',payload:{user_id:cloudUser.id,data:snapshot,updated_at:updatedAt}})}
  });
  return cloudWriteChain;
};
async function pullCloudNow(){
  if(!cloudUser||!supabase||cloudApplying)return;
  const {data,error}=await supabase.from('app_states').select('data,updated_at').eq('user_id',cloudUser.id).maybeSingle();
  if(error||!data?.data||!data.updated_at)return;
  applyCloudState(data.data,data.updated_at,'Đã đồng bộ dữ liệu mới');
}
window.addEventListener('focus',pullCloudNow);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')pullCloudNow()});

function installSidebarToggle(){
  const side=document.querySelector('.sidebar');if(!side)return;
  const saved=localStorage.getItem('so-tai-chinh-sidebar-collapsed')==='1';document.documentElement.classList.toggle('sidebar-collapsed',saved);
  if(!side.querySelector('#sidebar-toggle')){const b=document.createElement('button');b.id='sidebar-toggle';b.className='sidebar-toggle';b.type='button';b.title='Thu gọn menu';b.innerHTML='<span>☰</span><em>Thu gọn menu</em>';b.onclick=()=>{const collapsed=!document.documentElement.classList.contains('sidebar-collapsed');document.documentElement.classList.toggle('sidebar-collapsed',collapsed);localStorage.setItem('so-tai-chinh-sidebar-collapsed',collapsed?'1':'0');b.title=collapsed?'Mở rộng menu':'Thu gọn menu';b.innerHTML=`<span>${collapsed?'☰':'×'}</span><em>${collapsed?'Mở rộng menu':'Thu gọn menu'}</em>`};side.querySelector('.brand')?.after(b)}
}
const layoutWithSidebar=layout;
layout=function(){layoutWithSidebar();installSidebarToggle()};
if(document.querySelector('.sidebar'))layout();
